Kopi Susu
Teh Tarik
// === main.js ===
import { readFile, writeFile, appendFile } from 'node:fs/promises';
const menu = (await readFile('menu.txt', 'utf8')).trim().split('\n');
console.log(menu);
await writeFile('menu.txt', menu.join('\n') + '\nRoti Bakar\n');
await appendFile('menu.txt', 'Es Jeruk\n');
const baru = await readFile('menu.txt', 'utf8');
console.log(baru.trim().split('\n').length);
const mentah = await readFile('menu.txt');
console.log(mentah.length, typeof baru);

