// === angka.txt ===
10
20
30
// === main.js ===
import { readFile } from 'node:fs/promises';
const isi = await readFile('angka.txt', 'utf8');
const jumlah = isi.trim().split('\n').map(Number).reduce((a, b) => a + b, 0);
console.log('Jumlah:', jumlah);
